import{_ as t,o,c as a,a2 as s}from"./chunks/framework.CHeM0PsO.js";const m=JSON.parse('{"title":"Sovereign Mobile — Development Workflow","description":"","frontmatter":{"sourceUrl":"https://github.com/sovereignfs/sovereign-mobile/blob/main/docs/development-workflow.md"},"headers":[],"relativePath":"apps/mobile/development-workflow.md","filePath":"apps/mobile/development-workflow.md"}'),r={name:"apps/mobile/development-workflow.md"};function d(i,e,n,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="sovereign-mobile-—-development-workflow" tabindex="-1">Sovereign Mobile — Development Workflow <a class="header-anchor" href="#sovereign-mobile-—-development-workflow" aria-label="Permalink to &quot;Sovereign Mobile — Development Workflow&quot;">​</a></h1><p>How tasks are planned, started, implemented, and closed out. Designed for agentic execution with human oversight.</p><p>Adapted from <code>sovereign-edge</code>&#39;s <code>docs/development-workflow.md</code>, which is itself adapted from <code>sovereign</code>&#39;s. The shape is kept the same across ecosystem repos so moving between them doesn&#39;t mean relearning it; the parts that presuppose a monorepo or an SRS are not carried over — see <a href="#not-adopted-yet">Not adopted</a>.</p><hr><h2 id="four-layer-information-architecture" tabindex="-1">Four-layer information architecture <a class="header-anchor" href="#four-layer-information-architecture" aria-label="Permalink to &quot;Four-layer information architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AGENTS.md / CLAUDE.md      ← conventions and hard rules; no task pointer</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └─▶ ROADMAP.md         ← chronological index; one row per task; canonical status</span></span>
<span class="line"><span>            │</span></span>
<span class="line"><span>            └─▶ docs/epics/&lt;domain&gt;.md   ← full task detail: Goal, Deliverables,</span></span>
<span class="line"><span>            │                              Dependencies, Review checklist</span></span>
<span class="line"><span>            │</span></span>
<span class="line"><span>            └─▶ docs/adrs/ + docs/research/  ← why: locked decisions and open questions</span></span></code></pre></div><p>This repo adds one layer <code>sovereign-edge</code> doesn&#39;t have: <strong>ADRs</strong> (<code>docs/adrs/</code>), because several of this repo&#39;s foundational decisions (shell technology, distribution model, auth model, bridge sharing) were already locked centrally before this repo existed, and need a durable record independent of the research process that produced them. See <a href="./adrs/README.html">docs/adrs/README.md</a> for why, and how ADRs differ from research docs here.</p><table tabindex="0"><thead><tr><th>File</th><th>Job</th><th>Read it for</th></tr></thead><tbody><tr><td><code>AGENTS.md</code></td><td>Conventions and hard rules</td><td>How to work here; what must never be violated</td></tr><tr><td><code>CLAUDE.md</code></td><td>Claude Code adapter</td><td>Nothing — it points at <code>AGENTS.md</code></td></tr><tr><td><code>ROADMAP.md</code></td><td>Version-ordered task index</td><td>Which tasks exist, their status, which epic file</td></tr><tr><td><code>docs/epics/&lt;file&gt;.md</code></td><td>Full task spec</td><td>Goal, deliverables, review checklist</td></tr><tr><td><code>docs/adrs/&lt;n&gt;-*.md</code></td><td>Decision record (binding)</td><td>What was decided and its consequences</td></tr><tr><td><code>docs/research/&lt;n&gt;-*.md</code></td><td>Decision record (open question)</td><td>Options considered before (or absent) a decision</td></tr></tbody></table><p>There is no &quot;next task&quot; pointer anywhere in this stack. <strong>The developer assigns the next task at session start.</strong> A stored pointer goes stale the moment priorities shift, and two agents reading it would collide.</p><hr><h2 id="epic-structure" tabindex="-1">Epic structure <a class="header-anchor" href="#epic-structure" aria-label="Permalink to &quot;Epic structure&quot;">​</a></h2><p>Work is organized into domain epics, indexed in <a href="./epics/README.html">docs/epics/README.md</a>: shell, bridge, release. Each task carries the <strong>stable epic task ID</strong> it was assigned centrally in the <code>sovereign</code> monorepo&#39;s epic 20 (e.g. <code>20.1</code>) — this repo does not renumber tasks it shares with the monorepo.</p><h3 id="stable-ids-vs-volatile-slots" tabindex="-1">Stable IDs vs volatile slots <a class="header-anchor" href="#stable-ids-vs-volatile-slots" aria-label="Permalink to &quot;Stable IDs vs volatile slots&quot;">​</a></h3><p><strong>Epic task IDs are permanent</strong> and shared with <code>sovereign</code>. Use them in commit subjects, PR titles, and cross-references.</p><p><strong>Roadmap slot versions are this repo&#39;s own and volatile.</strong> A slot like <code>0.1.2</code> reflects current sequencing here and shifts when priorities change. Look the live slot up in <code>ROADMAP.md</code>; keep slots out of branch names and commit subjects.</p><hr><h2 id="task-lifecycle" tabindex="-1">Task lifecycle <a class="header-anchor" href="#task-lifecycle" aria-label="Permalink to &quot;Task lifecycle&quot;">​</a></h2><h3 id="starting-a-task" tabindex="-1">Starting a task <a class="header-anchor" href="#starting-a-task" aria-label="Permalink to &quot;Starting a task&quot;">​</a></h3><ol><li>The developer names the task (epic task ID or description).</li><li>Confirm <code>main</code> is clean and up to date: <code>git switch main &amp;&amp; git pull</code>.</li><li>Look up the epic file via <a href="./epics/README.html">docs/epics/README.md</a> and read the full task block — goal, deliverables, dependencies, review checklist.</li><li>Read any ADR or research doc the task references. <strong>Do not re-decide an Accepted ADR</strong> — if a task seems to require reopening one, stop and say so rather than quietly working around it.</li><li>If the task turns on a genuinely open question with no ADR yet, write the research doc first.</li><li>Cut the branch: <code>feat/&lt;slug&gt;</code>, <code>fix/&lt;slug&gt;</code>, <code>docs/&lt;slug&gt;</code>, or <code>chore/&lt;slug&gt;</code>.</li></ol><h3 id="during-implementation" tabindex="-1">During implementation <a class="header-anchor" href="#during-implementation" aria-label="Permalink to &quot;During implementation&quot;">​</a></h3><ul><li><strong>One task at a time.</strong> Do not start a task on an unmerged PR.</li><li>Commit as you go, with messages that explain <em>why</em>.</li><li>When something you assumed turns out to be wrong, say so in the same turn rather than quietly correcting course.</li><li><strong>Cross-repo tasks</strong> (several bridge/release tasks depend on work owned in the <code>sovereign</code> monorepo — see <a href="./epics/README.html#owned-elsewhere-referenced-here">docs/epics/README.md</a>) may need to wait on that repo&#39;s own PR queue. The &quot;previous leg&#39;s PR must be merged first&quot; rule applies <strong>per repository</strong>, not across them — see sovereign workstream 0002&#39;s &quot;Cross-repo parallelism&quot; note for the precedent.</li></ul><h3 id="completing-a-task" tabindex="-1">Completing a task <a class="header-anchor" href="#completing-a-task" aria-label="Permalink to &quot;Completing a task&quot;">​</a></h3><ol><li><strong>Verify.</strong> Run the checks in <a href="./../CONTRIBUTING.html">CONTRIBUTING.md</a> — and then actually exercise the change (see Verification, below).</li><li><strong>Update status.</strong> Mark the task ✅ in <code>ROADMAP.md</code> <em>and</em> the matching <code>docs/epics/&lt;file&gt;.md</code> heading, in the same PR.</li><li><strong>Record decisions.</strong> If the task settled an open question, promote the relevant research doc into a new ADR (or update an existing one) rather than leaving the decision only in a PR description.</li><li><strong>Open a draft PR</strong> with <code>gh pr create --draft</code>. Mark it ready for review only on explicit instruction, and <strong>never merge automatically.</strong></li></ol><hr><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Running checks is necessary, not sufficient. The review checklist in each epic task describes an observable behavior — that is the thing to demonstrate, on a real build, not just a passing test suite.</p><p><code>sovereign-edge</code>&#39;s history has two concrete examples of a fully green suite hiding a real bug: a stall watchdog that reported the wrong error code because a promise race only occurs against a real download, and a build step (<code>expo prebuild</code>) that exits 0 when the platform-native step it depends on actually failed. The applicable lesson here: <strong>check the artefact, not the exit code</strong>, and for anything with a runtime surface, drive it on a real simulator/emulator — or, where the task&#39;s review checklist says so, a physical device (see <a href="./epics/shell.html">docs/epics/shell.md</a> Risks: simulator-only verification is explicitly insufficient for the shell-loads-and-authenticates check).</p><hr><h2 id="status-tracking" tabindex="-1">Status tracking <a class="header-anchor" href="#status-tracking" aria-label="Permalink to &quot;Status tracking&quot;">​</a></h2><p>Status lives in exactly two places:</p><table tabindex="0"><thead><tr><th>Location</th><th>Tracks</th></tr></thead><tbody><tr><td><code>ROADMAP.md</code> row Status cell</td><td>✅ / ⏳ / 📋 per task — the canonical record</td></tr><tr><td>Open PRs</td><td>Which tasks are currently in flight</td></tr></tbody></table><p>Epic file headings (<code>#### ✅ X.Y — …</code>) are updated when a task completes. Close a task by marking <strong>both</strong> the roadmap row and the epic heading in the same PR. Do not accumulate completion history in <code>AGENTS.md</code> or <code>CLAUDE.md</code>.</p><hr><h2 id="adrs-vs-research-docs" tabindex="-1">ADRs vs research docs <a class="header-anchor" href="#adrs-vs-research-docs" aria-label="Permalink to &quot;ADRs vs research docs&quot;">​</a></h2><ul><li><strong>ADR</strong> (<code>docs/adrs/</code>): a decision with binding consequences, <code>Accepted</code> by default here whenever it restates something already locked centrally (see <a href="./adrs/README.html">docs/adrs/README.md</a>), or moved through <code>Proposed</code> → <code>Accepted</code> when decided in this repo directly.</li><li><strong>Research</strong> (<code>docs/research/</code>): an open question, or the record of how a now-Accepted ADR was reached. Write one <strong>before</strong> building on an unverified assumption. &quot;Not now&quot; and &quot;rejected&quot; are valid outcomes.</li></ul><p>When a research question resolves into a binding decision, write the ADR and leave the research doc as-is (don&#39;t delete it) with a status line pointing at the ADR — see <a href="./research/0001-shell-and-bridge-technology-choice.html">research 0001</a> for the pattern.</p><hr><h2 id="not-adopted-yet" tabindex="-1">Not adopted (yet) <a class="header-anchor" href="#not-adopted-yet" aria-label="Permalink to &quot;Not adopted (yet)&quot;">​</a></h2><p>Machinery <code>sovereign</code>&#39;s workflow includes that this repo does not need at its current size — recorded so the divergence is deliberate:</p><table tabindex="0"><thead><tr><th>Not adopted</th><th>Why</th></tr></thead><tbody><tr><td><code>CURRENT_TASK.md</code></td><td>A transient task-scratch file written by <code>sovereign</code>-specific <code>/sv-*</code> skills that don&#39;t exist here</td></tr><tr><td>Workstreams and legs (as a formal artifact)</td><td>This repo&#39;s own roadmap is one task at a time; cross-repo sequencing is tracked in <code>sovereign</code>&#39;s workstream 0002 instead of duplicated here</td></tr><tr><td>SRS references</td><td>No SRS here. ADRs and epic files carry the requirement detail</td></tr><tr><td>Per-package version bumps</td><td>Single app, single <code>package.json</code>. Version tracks the roadmap slot of the last completed task</td></tr></tbody></table><p>Revisit these if this repo outgrows the simpler model, not before.</p><hr><h2 id="quick-reference" tabindex="-1">Quick reference <a class="header-anchor" href="#quick-reference" aria-label="Permalink to &quot;Quick reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>I need to know…</th><th>Read…</th></tr></thead><tbody><tr><td>What task is next</td><td>Ask the developer; <code>ROADMAP.md</code> lists what&#39;s pending</td></tr><tr><td>Full spec for a task by epic ID</td><td><code>docs/epics/&lt;file&gt;.md</code> — grep for <code>^#### .*&lt;id&gt;</code></td></tr><tr><td>Which epic a task belongs to</td><td><code>docs/epics/README.md</code></td></tr><tr><td>Why a decision was locked</td><td><code>docs/adrs/</code> — index at <code>docs/adrs/README.md</code></td></tr><tr><td>An open question with no decision yet</td><td><code>docs/research/</code> — index at <code>docs/research/README.md</code></td></tr><tr><td>Project conventions and hard rules</td><td><code>AGENTS.md</code></td></tr><tr><td>Setup, branching, commits, PRs, CI</td><td><code>CONTRIBUTING.md</code></td></tr></tbody></table>`,44)])])}const u=t(r,[["render",d]]);export{m as __pageData,u as default};
